const ACCENT: CSSProperties = { stroke: "var(--icon-accent)" };

type Props = Omit<SVGProps<SVGSVGElement>, "ref"> & {
  size?: number | string;
  strokeWidth?: number | string;
};

/** One brand icon; takes Lucide's props so icons.tsx can swap it in by key. */
export function brandIcon(name: BrandIconName) {
  const paths = BRAND_PATHS[name];
  function BrandIcon({ size = 24, strokeWidth = 2, color = "currentColor", ...rest }: Props) {
    return (
      // biome-ignore lint/a11y/noSvgWithoutTitle: callers pass aria-hidden, or role="img" + aria-label, as with Lucide
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        {...rest}
      >
        {paths.map((p) => (
          <path key={p[0]} d={p[0]} {...(p.length === 2 ? { style: ACCENT } : {})} />
        ))}
      </svg>
    );
  }
  BrandIcon.displayName = `BrandIcon(${name})`;
  return BrandIcon;
}
